option.value:
/**
 * Space Detail Page Styles
 * Professional Airbnb-inspired design
 */

.space-detail-page {
  background: var(--white);
  min-height: 100vh;
}

/* Loading & Error */
.loading-container,
.error-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 60vh;
  gap: var(--space-4);
}

.spinner {
  width: 48px;
  height: 48px;
  border: 4px solid var(--gray-200);
  border-top-color: var(--primary-600);
  border-radius: var(--radius-full);
  animation: spin 1s linear infinite;
}

/* Breadcrumbs */
.breadcrumbs {
  padding: var(--space-4) 0;
  border-bottom: 1px solid var(--gray-200);

  .container {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    font-size: var(--text-sm);
  }

  a {
    color: var(--gray-600);
    text-decoration: none;
    transition: color var(--transition-fast);

    &:hover {
      color: var(--primary-600);
    }
  }

  .separator {
    color: var(--gray-400);
  }

  span:last-child {
    color: var(--gray-900);
    font-weight: var(--font-medium);
  }
}

/* Header */
.space-header {
  padding: var(--space-6) 0;

  .header-content {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: var(--space-6);
  }
}

.space-title {
  font-size: var(--text-3xl);
  font-weight: var(--font-bold);
  margin: 0 0 var(--space-3);
  line-height: var(--leading-tight);
}

.space-meta {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--text-sm);
  color: var(--gray-700);
}

.rating-container {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.reviews-count {
  color: var(--gray-600);
  text-decoration: underline;
  cursor: pointer;
}

.meta-separator {
  color: var(--gray-400);
}

.header-actions {
  display: flex;
  gap: var(--space-2);
}

/* Gallery */
.gallery-section {
  padding: var(--space-6) 0;
  position: relative;
}

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(2, 250px);
  gap: var(--space-2);
  border-radius: var(--radius-2xl);
  overflow: hidden;
}

.gallery-item {
  position: relative;
  overflow: hidden;
  cursor: pointer;
  transition: all var(--transition-base);

  &.main-image {
    grid-column: span 2;
    grid-row: span 2;
  }

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
  }

  &:hover {
    img {
      transform: scale(1.05);
    }
  }
}

.more-photos-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: var(--font-semibold);
  font-size: var(--text-lg);
}

.show-all-photos {
  position: absolute;
  bottom: var(--space-8);
  right: var(--space-8);
  z-index: 10;
}

/* Main Content */
.main-content {
  padding: var(--space-12) 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: var(--space-12);
  align-items: start;
}

.content-main {
  display: flex;
  flex-direction: column;
  gap: var(--space-12);
}

.content-section {
  padding-bottom: var(--space-12);
  border-bottom: 1px solid var(--gray-200);

  &:last-child {
    border-bottom: none;
  }

  h2 {
    font-size: var(--text-2xl);
    font-weight: var(--font-bold);
    margin: 0 0 var(--space-6);
  }
}

/* Highlights */
.space-highlights {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
}

.highlight-item {
  display: flex;
  gap: var(--space-4);
  align-items: center;

  svg {
    color: var(--gray-600);
    flex-shrink: 0;
  }

  strong {
    display: block;
    font-weight: var(--font-semibold);
    color: var(--gray-900);
  }

  p {
    margin: 0;
    color: var(--gray-600);
    font-size: var(--text-sm);
  }
}

.space-description {
  font-size: var(--text-base);
  line-height: var(--leading-relaxed);
  color: var(--gray-700);
}

/* Amenities */
.amenities-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
  margin-bottom: var(--space-4);
}

.amenity-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--text-base);
  color: var(--gray-700);

  .amenity-icon {
    font-size: var(--text-2xl);
  }
}

/* Reviews */
.reviews-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-8);
}

.reviews-summary {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.reviews-text {
  color: var(--gray-700);
  font-weight: var(--font-medium);
}

.reviews-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-8);
}

.review-item {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.review-header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.reviewer-avatar {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--primary-600);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: var(--font-bold);
  font-size: var(--text-lg);
}

.reviewer-info {
  display: flex;
  flex-direction: column;

  strong {
    font-weight: var(--font-semibold);
    color: var(--gray-900);
  }
}

.review-date {
  font-size: var(--text-sm);
  color: var(--gray-600);
}

.review-comment {
  font-size: var(--text-base);
  line-height: var(--leading-relaxed);
  color: var(--gray-700);
  margin: 0;
}

/* Location */
.location-info {
  p {
    margin-bottom: var(--space-4);
  }
}

.map-placeholder {
  background: var(--gray-100);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: var(--space-20);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  color: var(--gray-500);

  svg {
    color: var(--gray-400);
  }

  p {
    margin: 0;
  }
}

/* Booking Sidebar */
.booking-sidebar {
  position: relative;
}

.booking-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-2xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-xl);

  &.sticky {
    position: sticky;
    top: 100px;
  }
}

.booking-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-6);
  border-bottom: 1px solid var(--gray-200);
}

.price-info {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.price {
  font-size: var(--text-3xl);
  font-weight: var(--font-bold);
  color: var(--gray-900);
}

.price-unit {
  font-size: var(--text-base);
  color: var(--gray-600);
}

.booking-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3);
}

.price-breakdown {
  padding: var(--space-4);
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  margin: var(--space-4) 0;
}

.price-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: var(--text-base);

  .price-value {
    font-weight: var(--font-semibold);
    color: var(--gray-900);
  }
}

.booking-note {
  text-align: center;
  font-size: var(--text-sm);
  color: var(--gray-600);
  margin: var(--space-4) 0 0;
}

/* Gallery Modal */
.gallery-modal {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.95);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-8);
  animation: fadeIn var(--transition-base) var(--ease-out);
}

.modal-close {
  position: absolute;
  top: var(--space-6);
  right: var(--space-6);
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);

  &:hover {
    background: rgba(255, 255, 255, 0.2);
  }
}

.gallery-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 56px;
  height: 56px;
  border-radius: var(--radius-full);
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
  z-index: 10001;

  &:hover {
    background: rgba(255, 255, 255, 0.2);
    transform: translateY(-50%) scale(1.1);
  }

  &.prev {
    left: var(--space-6);
  }

  &.next {
    right: var(--space-6);
  }
}

.gallery-image-container {
  position: relative;
  max-width: 90vw;
  max-height: 90vh;

  img {
    max-width: 100%;
    max-height: 90vh;
    object-fit: contain;
    border-radius: var(--radius-xl);
  }
}

.gallery-counter {
  position: absolute;
  bottom: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.6);
  color: var(--white);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
}

/* Responsive */
@media (max-width: 1279px) {
  .content-grid {
    grid-template-columns: 1fr 320px;
  }
}

@media (max-width: 1023px) {
  .content-grid {
    grid-template-columns: 1fr;
  }

  .booking-sidebar {
    order: -1;
  }

  .booking-card.sticky {
    position: static;
  }

  .gallery-grid {
    grid-template-rows: repeat(2, 200px);
  }
}

@media (max-width: 767px) {
  .space-title {
    font-size: var(--text-2xl);
  }

  .header-content {
    flex-direction: column;
  }

  .gallery-grid {
    grid-template-columns: 1fr;
    grid-template-rows: repeat(3, 200px);

    .gallery-item.main-image {
      grid-column: 1;
      grid-row: 1;
    }
  }

  .show-all-photos {
    bottom: var(--space-4);
    right: var(--space-4);
  }

  .amenities-list {
    grid-template-columns: 1fr;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .gallery-nav {
    width: 44px;
    height: 44px;

    svg {
      width: 24px;
      height: 24px;
    }
  }

  .modal-close {
    width: 40px;
    height: 40px;
  }
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { SpacesService, Space } from '../../../core/services/spaces.service';
import { BookingsService, CreateBookingDTO } from '../../../core/services/bookings.service';

@Component({
  selector: 'app-space-detail',
  imports: [CommonModule, FormsModule, ReactiveFormsModule, RouterModule],
  templateUrl: './space-detail.html',
  styleUrl: './space-detail.scss'
})
export class SpaceDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private fb = inject(FormBuilder);
  private spacesService = inject(SpacesService);
  private bookingsService = inject(BookingsService);

  space: Space | null = null;
  loading = true;
  error: string | null = null;

  bookingForm: FormGroup;
  bookingLoading = false;
  bookingError: string | null = null;
  estimatedPrice: number | null = null;

  selectedImageIndex = 0;
  showAllAmenities = false;

  // Reviews reales - se cargarán del backend cuando se implemente
  reviews: any[] = [];

  constructor() {
    this.bookingForm = this.fb.group({
      startDate: ['', Validators.required],
      startTime: ['10:00', Validators.required],
      endDate: ['', Validators.required],
      endTime: ['18:00', Validators.required],
      numGuests: [1, [Validators.required, Validators.min(1)]]
    });

    // Calcular precio cuando cambian los valores
    this.bookingForm.valueChanges.subscribe(() => {
      this.calculatePrice();
    });
  }

  ngOnInit(): void {
    const spaceId = this.route.snapshot.paramMap.get('id');
    if (spaceId) {
      this.loadSpace(spaceId);
    } else {
      this.router.navigate(['/']);
    }
  }

  loadSpace(id: string): void {
    this.loading = true;
    this.error = null;

    this.spacesService.getSpaceById(id).subscribe({
      next: (space) => {
        this.space = space;
        this.loading = false;
        console.log('✅ Espacio cargado:', space);
      },
      error: (error) => {
        console.error('❌ Error cargando espacio:', error);
        this.error = 'No se pudo cargar el espacio. Verifica que exista y el backend esté corriendo.';
        this.loading = false;
      }
    });
  }

  getImages(): string[] {
    if (!this.space || !this.space.images || this.space.images.length === 0) {
      // Placeholder si no hay imágenes
      return [
        `https://via.placeholder.com/1200x800/E5E7EB/6B7280?text=${encodeURIComponent(this.space?.title || 'Sin imagen')}`
      ];
    }

    // Retornar las URLs de las imágenes reales, ordenadas (principal primero)
    const sorted = [...this.space.images].sort((a, b) => {
      if (a.isPrimary) return -1;
      if (b.isPrimary) return 1;
      return a.displayOrder - b.displayOrder;
    });

    return sorted.map(img => img.url);
  }

  selectImage(index: number): void {
    this.selectedImageIndex = index;
  }

  calculatePrice(): void {
    if (!this.space || !this.bookingForm.valid) {
      this.estimatedPrice = null;
      return;
    }

    const values = this.bookingForm.value;
    const startDateTime = new Date(`${values.startDate}T${values.startTime}`);
    const endDateTime = new Date(`${values.endDate}T${values.endTime}`);

    const hours = (endDateTime.getTime() - startDateTime.getTime()) / (1000 * 60 * 60);

    if (hours > 0) {
      const pricePerHour = this.space.basePriceCents / 100;
      this.estimatedPrice = Math.round(pricePerHour * hours);
    } else {
      this.estimatedPrice = null;
    }
  }

  onSubmitBooking(): void {
    if (!this.bookingForm.valid || !this.space) {
      return;
    }

    const userId = localStorage.getItem('userId');
    if (!userId) {
      this.router.navigate(['/login'], {
        queryParams: { returnUrl: this.router.url }
      });
      return;
    }

    this.bookingLoading = true;
    this.bookingError = null;

    const values = this.bookingForm.value;
    const startTs = new Date(`${values.startDate}T${values.startTime}`).toISOString();
    const endTs = new Date(`${values.endDate}T${values.endTime}`).toISOString();

    const bookingData: CreateBookingDTO = {
      spaceId: this.space.id,
      guestId: userId,
      startTs: startTs,
      endTs: endTs,
      numGuests: values.numGuests
    };

    this.bookingsService.createBooking(bookingData).subscribe({
      next: (booking) => {
        console.log('✅ Reserva creada:', booking);
        this.bookingLoading = false;
        // Redirigir a página de pago o confirmación
        this.router.navigate(['/bookings', booking.id, 'payment']);
      },
      error: (error) => {
        console.error('❌ Error creando reserva:', error);
        this.bookingError = error.error?.message || 'Error al crear la reserva';
        this.bookingLoading = false;
      }
    });
  }

  getAmenityIcon(amenity: string): string {
    const icons: { [key: string]: string } = {
      'wifi': '',
      'cocina': '',
      'aire_acondicionado': '❄️',
      'calefaccion': '',
      'terraza': '️',
      'parking': '️',
      'ascensor': '',
      'accesible': '♿',
      'mascotas': '',
      'proyector': '️',
      'sonido': '',
      'wifi_pro': ''
    };
    return icons[amenity] || '✓';
  }

  getAmenityName(amenity: string): string {
    const names: { [key: string]: string } = {
      'wifi': 'WiFi',
      'cocina': 'Cocina equipada',
      'aire_acondicionado': 'Aire acondicionado',
      'calefaccion': 'Calefacción',
      'terraza': 'Terraza',
      'parking': 'Parking',
      'ascensor': 'Ascensor',
      'accesible': 'Accesible',
      'mascotas': 'Se admiten mascotas',
      'proyector': 'Proyector',
      'sonido': 'Sistema de sonido',
      'wifi_pro': 'WiFi profesional',
      'vistas': 'Vistas',
      'iluminacion': 'Iluminación profesional',
      'pizarra': 'Pizarra',
      'cafe': 'Café',
      'jardin': 'Jardín',
      'bao': 'Baño',
      'cocina_exterior': 'Cocina exterior'
    };
    return names[amenity] || amenity;
  }

  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }).format(date);
  }

  goBack(): void {
    this.router.navigate(['/']);
  }

  shareSpace(): void {
    if (navigator.share && this.space) {
      navigator.share({
        title: this.space.title,
        text: this.space.description,
        url: window.location.href
      }).catch(err => console.log('Error sharing:', err));
    } else {
      // Fallback: copiar al portapapeles
      navigator.clipboard.writeText(window.location.href);
      alert('¡Enlace copiado al portapapeles!');
    }
  }

  toggleFavorite(): void {
    // TODO: Implementar sistema de favoritos
    console.log('Toggle favorite');
  }
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { SpacesService, Space } from '../../../core/services/spaces.service';
import { BookingsService, CreateBookingDTO } from '../../../core/services/bookings.service';
import { RatingStarsComponent } from '../../../shared/components/rating-stars/rating-stars';
import { PricePipe } from '../../../shared/pipes/price.pipe';

@Component({
  selector: 'app-space-detail',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    RouterModule,
    RatingStarsComponent,
    PricePipe
  ],
  templateUrl: './space-detail.html',
  styleUrl: './space-detail.scss'
})
export class SpaceDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private fb = inject(FormBuilder);
  private spacesService = inject(SpacesService);
  private bookingsService = inject(BookingsService);

  space: Space | null = null;
  loading = true;
  error: string | null = null;

  bookingForm: FormGroup;
  bookingLoading = false;
  bookingError: string | null = null;
  estimatedPrice: number | null = null;

  // Gallery
  selectedImageIndex = 0;
  showGalleryModal = false;

  // Amenities
  showAllAmenities = false;

  // Reviews (mock para este PR, se implementarán con backend)
  reviews: any[] = [
    {
      id: 1,
      guestName: 'María García',
      rating: 5,
      comment: 'Espacio increíble, perfecto para nuestra reunión. El anfitrión fue muy atento.',
      date: '2025-10-15',
      guestAvatar: 'M'
    },
    {
      id: 2,
      guestName: 'Carlos Ruiz',
      rating: 4,
      comment: 'Muy buen lugar, cómodo y bien ubicado. Solo faltaba un poco más de iluminación.',
      date: '2025-10-08',
      guestAvatar: 'C'
    }
  ];
  averageRating = 4.5;
  totalReviews = 2;

  constructor() {
    this.bookingForm = this.fb.group({
      startDate: ['', Validators.required],
      startTime: ['10:00', Validators.required],
      endDate: ['', Validators.required],
      endTime: ['18:00', Validators.required],
      numGuests: [1, [Validators.required, Validators.min(1)]]
    });

    this.bookingForm.valueChanges.subscribe(() => {
      this.calculatePrice();
    });
  }

  ngOnInit(): void {
    const spaceId = this.route.snapshot.paramMap.get('id');
    if (spaceId) {
      this.loadSpace(spaceId);
    } else {
      this.router.navigate(['/']);
    }
  }

  loadSpace(id: string): void {
    this.loading = true;
    this.error = null;

    this.spacesService.getSpaceById(id).subscribe({
      next: (space) => {
        this.space = space;
        this.loading = false;
        console.log('✅ Espacio cargado:', space);
      },
      error: (error) => {
        console.error('❌ Error cargando espacio:', error);
        this.error = 'No se pudo cargar el espacio. Verifica que exista y el backend esté corriendo.';
        this.loading = false;
      }
    });
  }

  getImages(): string[] {
    if (!this.space || !this.space.images || this.space.images.length === 0) {
      // Placeholder si no hay imágenes
      return [
        `https://via.placeholder.com/1200x800/E5E7EB/6B7280?text=${encodeURIComponent(this.space?.title || 'Sin imagen')}`
      ];
    }

    // Retornar las URLs de las imágenes reales, ordenadas (principal primero)
    const sorted = [...this.space.images].sort((a, b) => {
      if (a.isPrimary) return -1;
      if (b.isPrimary) return 1;
      return a.displayOrder - b.displayOrder;
    });

    return sorted.map(img => img.url);
  }

  selectImage(index: number): void {
    this.selectedImageIndex = index;
  }

  calculatePrice(): void {
    if (!this.space || !this.bookingForm.valid) {
      this.estimatedPrice = null;
      return;
    }

    const values = this.bookingForm.value;
    const startDateTime = new Date(`${values.startDate}T${values.startTime}`);
    const endDateTime = new Date(`${values.endDate}T${values.endTime}`);

    const hours = (endDateTime.getTime() - startDateTime.getTime()) / (1000 * 60 * 60);

    if (hours > 0) {
      const pricePerHour = this.space.basePriceCents / 100;
      this.estimatedPrice = Math.round(pricePerHour * hours);
    } else {
      this.estimatedPrice = null;
    }
  }

  onSubmitBooking(): void {
    if (!this.bookingForm.valid || !this.space) {
      return;
    }

    const userId = localStorage.getItem('userId');
    if (!userId) {
      this.router.navigate(['/login'], {
        queryParams: { returnUrl: this.router.url }
      });
      return;
    }

    this.bookingLoading = true;
    this.bookingError = null;

    const values = this.bookingForm.value;
    const startTs = new Date(`${values.startDate}T${values.startTime}`).toISOString();
    const endTs = new Date(`${values.endDate}T${values.endTime}`).toISOString();

    const bookingData: CreateBookingDTO = {
      spaceId: this.space.id,
      guestId: userId,
      startTs: startTs,
      endTs: endTs,
      numGuests: values.numGuests
    };

    this.bookingsService.createBooking(bookingData).subscribe({
      next: (booking) => {
        console.log('✅ Reserva creada:', booking);
        this.bookingLoading = false;
        // Redirigir a página de pago o confirmación
        this.router.navigate(['/bookings', booking.id, 'payment']);
      },
      error: (error) => {
        console.error('❌ Error creando reserva:', error);
        this.bookingError = error.error?.message || 'Error al crear la reserva';
        this.bookingLoading = false;
      }
    });
  }

  getAmenityIcon(amenity: string): string {
    const icons: { [key: string]: string } = {
      'wifi': '',
      'cocina': '',
      'aire_acondicionado': '❄️',
      'calefaccion': '',
      'terraza': '️',
      'parking': '️',
      'ascensor': '',
      'accesible': '♿',
      'mascotas': '',
      'proyector': '️',
      'sonido': '',
      'wifi_pro': ''
    };
    return icons[amenity] || '✓';
  }

  getAmenityName(amenity: string): string {
    const names: { [key: string]: string } = {
      'wifi': 'WiFi',
      'cocina': 'Cocina equipada',
      'aire_acondicionado': 'Aire acondicionado',
      'calefaccion': 'Calefacción',
      'terraza': 'Terraza',
      'parking': 'Parking',
      'ascensor': 'Ascensor',
      'accesible': 'Accesible',
      'mascotas': 'Se admiten mascotas',
      'proyector': 'Proyector',
      'sonido': 'Sistema de sonido',
      'wifi_pro': 'WiFi profesional',
      'vistas': 'Vistas',
      'iluminacion': 'Iluminación profesional',
      'pizarra': 'Pizarra',
      'cafe': 'Café',
      'jardin': 'Jardín',
      'bao': 'Baño',
      'cocina_exterior': 'Cocina exterior'
    };
    return names[amenity] || amenity;
  }

  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }).format(date);
  }

  goBack(): void {
    this.router.navigate(['/']);
  }

  shareSpace(): void {
    if (navigator.share && this.space) {
      navigator.share({
        title: this.space.title,
        text: this.space.description,
        url: window.location.href
      }).catch(err => console.log('Error sharing:', err));
    } else {
      // Fallback: copiar al portapapeles
      navigator.clipboard.writeText(window.location.href);
      alert('¡Enlace copiado al portapapeles!');
    }
  }

  toggleFavorite(): void {
    // TODO: Implementar sistema de favoritos
    console.log('Toggle favorite');
  }

  // Gallery methods
  openGallery(index: number): void {
    this.selectedImageIndex = index;
    this.showGalleryModal = true;
    document.body.style.overflow = 'hidden';
  }

  closeGallery(): void {
    this.showGalleryModal = false;
    document.body.style.overflow = '';
  }

  nextImage(): void {
    const images = this.getImages();
    this.selectedImageIndex = (this.selectedImageIndex + 1) % images.length;
  }

  prevImage(): void {
    const images = this.getImages();
    this.selectedImageIndex = (this.selectedImageIndex - 1 + images.length) % images.length;
  }

  get displayedAmenities(): string[] {
    if (!this.space?.amenities) return [];
    return this.showAllAmenities ? this.space.amenities : this.space.amenities.slice(0, 8);
  }

  get hasMoreAmenities(): boolean {
    return (this.space?.amenities?.length || 0) > 8;
  }

  toggleAmenities(): void {
    this.showAllAmenities = !this.showAllAmenities;
  }
}
